import 'dart:js_interop';
import 'dart:typed_data';

import 'package:web/web.dart' as web;

import 'document_delivery_contract.dart';

/// Browser delivery: turn the generated bytes into a Blob and trigger a real
/// download through a temporary anchor. This is what makes "Export PDF/CSV"
/// work on Flutter web, where `dart:io` (and therefore the old share-based
/// exporter) is not available.
class DocumentDelivery {
  const DocumentDelivery();

  Future<DeliveryResult> deliver({
    required Uint8List bytes,
    required String fileName,
    required String mimeType,
    required String subject,
    required String text,
  }) async {
    final blob = web.Blob(
      <JSAny>[bytes.toJS].toJS,
      web.BlobPropertyBag(type: mimeType),
    );
    final url = web.URL.createObjectURL(blob);
    final anchor = web.document.createElement('a') as web.HTMLAnchorElement
      ..href = url
      ..download = fileName
      ..style.display = 'none';

    web.document.body?.appendChild(anchor);
    anchor.click();
    anchor.remove();

    // Give the browser a moment to start the download before releasing the
    // object URL; revoking immediately cancels it in some engines.
    await Future<void>.delayed(const Duration(seconds: 1));
    web.URL.revokeObjectURL(url);

    return const DeliveryResult(delivered: true, location: 'Downloads');
  }
}
